-- M40 exact source-bound author handoff authority, before predecessor normalization.
DO $author_handoff_verify$
DECLARE item record;actual text;
BEGIN
 IF NOT EXISTS(SELECT FROM forge_agent.schema_migrations WHERE version=40) THEN RETURN;END IF;
 IF NOT EXISTS(SELECT FROM forge_agent.schema_migrations WHERE version=40 AND name='provider_author_handoff') THEN RAISE EXCEPTION 'Author handoff migration identity drift';END IF;
 FOR item IN SELECT * FROM(VALUES ('forge_agent._coding_author_canonical_json(jsonb)','["forge_agent_owner", false, ["search_path=pg_catalog, pg_temp"], ["forge_agent_owner=X/forge_agent_owner"]]'),('forge_agent._coding_author_feedback_proof(uuid,text)','["forge_agent_owner", true, ["search_path=pg_catalog, pg_temp"], ["forge_agent_owner=X/forge_agent_owner"]]'),('forge_agent._coding_author_handoff_legacy_source(oid,text)','["forge_agent_owner", false, ["search_path=pg_catalog, pg_temp"], ["forge_agent_owner=X/forge_agent_owner"]]'),('forge_agent.coding_workflow_author_feedback(uuid,text)','["forge_agent_owner", true, ["search_path=pg_catalog, pg_temp"], ["forge_agent=X/forge_agent_owner", "forge_agent_owner=X/forge_agent_owner"]]'),('forge_agent.coding_workflow_author_handoff(uuid)','["forge_agent_owner", true, ["search_path=pg_catalog, pg_temp"], ["forge_agent=X/forge_agent_owner", "forge_agent_owner=X/forge_agent_owner"]]'),('forge_agent.coding_workflow_author_profile(uuid)','["forge_agent_owner", true, ["search_path=pg_catalog, pg_temp"], ["forge_agent=X/forge_agent_owner", "forge_agent_owner=X/forge_agent_owner"]]'),('forge_agent.coding_workflow_role_granted(uuid,text,text)','["forge_agent_owner", true, ["search_path=pg_catalog, pg_temp"], ["forge_agent=X/forge_agent_owner", "forge_agent_owner=X/forge_agent_owner"]]'),('forge_coding_worker_api.claim(text,uuid,text[])','["forge_agent_owner", true, ["search_path=pg_catalog, pg_temp"], ["forge_agent_owner=X/forge_agent_owner", "forge_coding_worker=X/forge_agent_owner"]]'),('forge_coding_worker_api.read_feedback(uuid,uuid)','["forge_agent_owner", true, ["search_path=pg_catalog, pg_temp"], ["forge_agent_owner=X/forge_agent_owner", "forge_coding_worker=X/forge_agent_owner"]]'),('forge_coding_worker_api.read_workflow_feedback(uuid,uuid)','["forge_agent_owner", true, ["search_path=pg_catalog, pg_temp"], ["forge_agent_owner=X/forge_agent_owner", "forge_coding_worker=X/forge_agent_owner"]]')) expected(signature,shape) LOOP
  SELECT jsonb_build_array(pg_get_userbyid(p.proowner),p.prosecdef,p.proconfig,ARRAY(SELECT unnest(p.proacl::text[]) ORDER BY 1))::text INTO actual FROM pg_proc p WHERE p.oid=to_regprocedure(item.signature);
  IF actual IS DISTINCT FROM item.shape THEN RAISE EXCEPTION 'Author handoff function drift: %',item.signature;END IF;
 END LOOP;
END;$author_handoff_verify$;
